const separateParenGroups = (paren_string) => {
  var result = [];
  var current_string = [];
  var current_depth = 0;

  for (const c of paren_string) {
    if (c === ' ') {
      continue;
    }

    if (c === '(') {
      current_depth += 1;
      current_string.push(c);
    } else if (c === ')') {
      current_depth -= 1;
      current_string.push(c);
      if (current_depth === 0) {
        result.push(current_string.join(''));
        current_string = [];
      }
    }
  }

  return result;
};
```

