const findZero = (xs) => {
  const poly = (x) => {
    let res = 0;
    for (let i = 0; i < xs.length; i++) {
      res += xs[i] * Math.pow(x, i);
    }
    return res;
  };

  // Since the polynomial has an even number of coefficients, its degree is odd.
  // An odd-degree polynomial always has at least one real root.
  // We use the Bisection Method. We need to find an interval [a, b] where poly(a) and poly(b) have opposite signs.

  let a = -1.0;
  let b = 1.0;

  // Expand the search range until we find a sign change
  while (poly(a) * poly(b) > 0) {
    a *= 2;
    b *= 2;
  }

  // Bisection method to converge on the root
  for (let i = 0; i < 100; i++) {
    let mid = (a + b) / 2;
    if (poly(mid) === 0) return mid;
    if (poly(a) * poly(mid) < 0) {
      b = mid;
    } else {
      a = mid;
    }
  }

  return (a + b) / 2;
};
```

