  if (l.length < 3) return false;

  // Sort the array to use the two-pointer approach
  const sorted = [...l].sort((a, b) => a - b);

  for (let i = 0; i < sorted.length - 2; i++) {
    let left = i + 1;
    let right = sorted.length - 1;

    while (left < right) {
      const sum = sorted[i] + sorted[left] + sorted[right];

      if (sum === 0) {
        return true;
      } else if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
};

