const carRaceCollision = (n) => {
  /**
   * Problem Analysis:
   * There are n cars moving left-to-right (L->R) and n cars moving right-to-left (R->L).
   * Every car moving L->R will eventually encounter every car moving R->L because 
   * they start far apart and move toward each other on a straight line.
   * Since they pass through each other (or "continue moving in their trajectory"),
   * every pair consisting of one L->R car and one R->L car will collide exactly once.
   * 
   * Total collisions = (number of L->R cars) * (number of R->L cars)
   * Total collisions = n * n
   */
  return n * n;
};
```

