const startsOneEnds = (n) => {
  if (n === 1) {
    return 1;
  }
  // Total n-digit numbers = 9 * 10^(n-1)
  // Numbers starting with 1: 1 * 10^(n-1)
  // Numbers ending with 1: 9 * 10^(n-2)
  // Numbers starting AND ending with 1: 1 * 10^(n-2)
  // By Inclusion-Exclusion: (10^(n-1)) + (9 * 10^(n-2)) - (10^(n-2))
  // = 10 * 10^(n-2) + 9 * 10^(n-2) - 1 * 10^(n-2)
  // = 18 * 10^(n-2)
  return 18 * Math.pow(10, n - 2);
};
```

