const sortArray = (array) => {
  if (array.length === 0) return [];

  // Create a copy to avoid mutating the original array
  const arr = [...array];

  // Calculate the sum of the first and last index values
  const sum = arr[0] + arr[arr.length - 1];
  const isOdd = sum % 2 !== 0;

  // Sort ascending if sum is odd, descending if sum is even
  arr.sort((a, b) => {
    if (isOdd) {
      return a - b;
    } else {
      return b - a;
    }
  });

  return arr;
};
```

