const isBored = (S) => {
  if (!S) return 0;

  // Split the string into sentences based on '.', '?', or '!'
  // The regex /[.!?]/ splits the string at any of these delimiters
  const sentences = S.split(/[.!?]/);
  let count = 0;

  for (let sentence of sentences) {
    // Trim leading/trailing whitespace to isolate the first word
    const trimmed = sentence.trim();

    // Check if the sentence starts with the word "I"
    // We ensure it is exactly "I" and not a word starting with I (like "Ice")
    if (trimmed.startsWith('I')) {
      // Check if "I" is the whole word (either end of string or followed by space)
      if (trimmed.length === 1 || trimmed[1] === ' ') {
        count++;
      }
    }
  }

  return count;
};
