const encode = (message) => {
  let t = '';
  for (let i = 0; i < message.length; i++) {
    let char = message[i];
    let p = char.charCodeAt(0);

    // Swap case
    if (p >= 65 && p <= 90) {
      p += 32;
    } else if (p >= 97 && p <= 122) {
      p -= 32;
    }

    // Check if the resulting character is a vowel (case-insensitive)
    // Vowels: A(65), E(69), I(73), O(79), U(85), a(97), e(101), i(105), o(111), u(117)
    if (p === 65 || p === 69 || p === 73 || p === 79 || p === 85 || 
        p === 97 || p === 101 || p === 105 || p === 111 || p === 117) {
      p += 2;
    }

    t += String.fromCharCode(p);
  }
  return t;
};
