const skjkasdkd = (lst) => {
  const isPrime = (num) => {
    if (num < 2) return false;
    for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
      if (num % i === 0) return false;
    }
    return true;
  };

  let maxPrime = -1;

  for (let i = 0; i < lst.length; i++) {
    const val = lst[i];
    if (val > maxPrime && isPrime(val)) {
      maxPrime = val;
    }
  }

  if (maxPrime === -1) return 0;

  return maxPrime
    .toString()
    .split('')
    .reduce((sum, digit) => sum + parseInt(digit, 10), 0);
};
