const checkDictCase = (dict) => {
  const keys = Object.keys(dict);
  if (keys.length === 0) {
    return false;
  }

  let allLower = true;
  let allUpper = true;

  for (const key of keys) {
    // If the key is not a string, it cannot be strictly lower or upper case
    if (typeof key !== 'string') {
      return false;
    }

    if (key !== key.toLowerCase()) {
      allLower = false;
    }
    if (key !== key.toUpperCase()) {
      allUpper = false;
    }
  }

  return allLower || allUpper;
};
