const evenOddPalindrome = (n) => {
  let evenCount = 0;
  let oddCount = 0;

  for (let i = 1; i <= n; i++) {
    const s = i.toString();
    let isPalindrome = true;

    for (let j = 0; j < Math.floor(s.length / 2); j++) {
      if (s[j] !== s[s.length - 1 - j]) {
        isPalindrome = false;
        break;
      }
    }

    if (isPalindrome) {
      if (i % 2 === 0) {
        evenCount++;
      } else {
        oddCount++;
      }
    }
  }

  return [evenCount, oddCount];
};
```

