const moveOneBall = (arr) => {
  if (arr.length === 0) {
    return true;
  }

  // Create a copy of the array to avoid mutating the original input
  let currentArr = [...arr];
  let len = currentArr.length;

  for (let i = 0; i < len; i++) {
    let isSorted = true;
    for (let j = 1; j < len; j++) {
      if (currentArr[j] < currentArr[j - 1]) {
        isSorted = false;
        break;
      }
    }

    if (isSorted) {
      return true;
    }

    // Perform one right shift operation
    // Move the last element to the front
    let lastElement = currentArr.pop();
    currentArr.unshift(lastElement);
  }

  return false;
};
