const moveOneBall = (arr) => {
  if (arr.length === 0) return true;

  let dropCount = 0;
  const n = arr.length;

  for (let i = 0; i < n; i++) {
    // Compare current element with the next element (circularly)
    if (arr[i] > arr[(i + 1) % n]) {
      dropCount++;
    }
  }

  // A rotated sorted array of unique elements will have at most one 
  // point where the current element is greater than the next element.
  // If dropCount is 0, it's already sorted.
  // If dropCount is 1, it's a rotated sorted array.
  return dropCount <= 1;
};
```

