const sortArray = (arr) => {
  const countOnes = (num) => {
    // Handle negative numbers by using unsigned right shift 0
    // to get the 32-bit binary representation
    return (num >>> 0).toString(2).split('1').length - 1;
  };

  return [...arr].sort((a, b) => {
    const onesA = countOnes(a);
    const onesB = countOnes(b);

    if (onesA !== onesB) {
      return onesA - onesB;
    }
    return a - b;
  });
};
```

