const selectWords = (s, n) => {
  if (s === '') return [];

  const words = s.split(/\s+/);
  const result = [];
  const vowels = new Set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']);

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word === '') continue;

    let consonantCount = 0;
    for (let j = 0; j < word.length; j++) {
      if (!vowels.has(word[j])) {
        consonantCount++;
      }
    }

    if (consonantCount === n) {
      result.push(word);
    }
  }

  return result;
};
