const getOddCollatz = (n) => {
  let p = [];
  let t = n;

  // Generate the Collatz sequence and collect odd numbers
  // The sequence ends when it reaches 1 (which is odd and will be added)
  while (t !== 1) {
    if (t % 2 !== 0) {
      p.push(t);
      t = 3 * t + 1;
    } else {
      t = t / 2;
    }
  }

  // Add the final 1 to the list
  p.push(1);

  // Sort the resulting list in increasing order
  return p.sort((a, b) => a - b);
};
