const intersection = (interval1, interval2) => {
  // Find the boundaries of the intersection
  let lo = Math.max(interval1[0], interval2[0]);
  let hi = Math.min(interval1[1], interval2[1]);

  // If the intervals do not intersect or the intersection is a single point,
  // the length is 0 or negative.
  if (hi <= lo) {
    return 'NO';
  }

  // Calculate the length of the intersection
  let len = hi - lo;

  // Prime number check
  if (len < 2) {
    return 'NO';
  }
  for (let i = 2; i * i <= len; i++) {
    if (len % i === 0) {
      return 'NO';
    }
  }

  return 'YES';
};
