const minPath = (grid, k) => {
  const n = grid.length;
  let startRow = 0;
  let startCol = 0;

  // The lexicographically smallest path must start with the smallest possible value in the grid.
  // Since the grid contains all integers from 1 to N*N, the smallest value is always 1.
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) {
        startRow = i;
        startCol = j;
        break;
      }
    }
  }

  // If k is 1, the path is just [1].
  if (k === 1) {
    return [1];
  }

  // To make the path lexicographically smallest for k > 1, we want the second element
  // to be the smallest possible neighbor of the cell containing 1.
  // After reaching that smallest neighbor, the best strategy to keep the path minimal
  // is to bounce back and forth between 1 and that smallest neighbor.
  let minNeighbor = Infinity;
  const directions = [
    [-1, 0], [1, 0], [0, -1], [0, 1]
  ];

  for (const [dr, dc] of directions) {
    const nr = startRow + dr;
    const nc = startCol + dc;
    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
      if (grid[nr][nc] < minNeighbor) {
        minNeighbor = grid[nr][nc];
      }
    }
  }

  const result = [];
  for (let i = 0; i < k; i++) {
    // Even indices (0, 2, ...) get the value 1
    // Odd indices (1, 3, ...) get the smallest neighbor
    if (i % 2 === 0) {
      result.push(1);
    } else {
      result.push(minNeighbor);
    }
  }

  return result;
};
