const minPath = (grid, k) => {
  const n = grid.length;
  let minVal = Infinity;
  let startPos = null;

  // Find the cell with the minimum value to start the lexicographically smallest path
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] < minVal) {
        minVal = grid[r][c];
        startPos = [r, c];
      }
    }
  }

  // If k is 1, the path is just the minimum value cell
  if (k === 1) return [minVal];

  const [startR, startC] = startPos;
  const dr = [-1, 1, 0, 0];
  const dc = [0, 0, -1, 1];

  let minNeighbor = Infinity;
  for (let i = 0; i < 4; i++) {
    const nr = startR + dr[i];
    const nc = startC + dc[i];
    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
      minNeighbor = Math.min(minNeighbor, grid[nr][nc]);
    }
  }

  // To get the lexicographically smallest path of length k:
  // 1. Start at the smallest possible value (minVal).
  // 2. Move to the smallest possible neighbor (minNeighbor).
  // 3. If k > 2, the best strategy is to oscillate between the smallest value 
  //    and its smallest neighbor to keep the sequence as small as possible.
  const result = [];
  for (let i = 0; i < k; i++) {
    if (i % 2 === 0) {
      result.push(minVal);
    } else {
      result.push(minNeighbor);
    }
  }

  return result;
};
