const tri = (n) => {
  if (n === 0) {
    return [1];
  }
  if (n === 1) {
    return [1, 3];
  }

  let p = new Array(n + 1);
  p[0] = 1;
  p[1] = 3;

  for (let i = 2; i <= n; i++) {
    if (i % 2 === 0) {
      // tri(n) = 1 + n / 2, if n is even.
      p[i] = 1 + i / 2;
    } else {
      // tri(n) = tri(n - 1) + tri(n - 2) + tri(n + 1), if n is odd.
      // Since n is odd, n + 1 is even.
      // tri(n + 1) = 1 + (n + 1) / 2
      const tri_n_plus_1 = 1 + (i + 1) / 2;
      p[i] = p[i - 1] + p[i - 2] + tri_n_plus_1;
    }
  }

  return p;
};
