const fileNameCheck = (file_name) => {
  // Check for exactly one dot
  let t = file_name.split('.');
  if (t.length !== 2) {
    return 'No';
  }

  const namePart = t[0];
  const extensionPart = t[1];

  // Substring after the dot must be one of ['txt', 'exe', 'dll']
  if (extensionPart !== 'txt' && extensionPart !== 'exe' && extensionPart !== 'dll') {
    return 'No';
  }

  // Substring before the dot should not be empty
  if (namePart === '') {
    return 'No';
  }

  // Substring before the dot must start with a latin alphabet letter
  const firstChar = namePart[0].toLowerCase();
  if (!(firstChar >= 'a' && firstChar <= 'z')) {
    return 'No';
  }

  // There should not be more than three digits ('0'-'9') in the entire file's name
  let digitCount = 0;
  for (let i = 0; i < file_name.length; i++) {
    if (file_name[i] >= '0' && file_name[i] <= '9') {
      digitCount++;
    }
  }

  if (digitCount > 3) {
    return 'No';
  }

  return 'Yes';
};
