const orderByPoints = (nums) => {
  const getDigitSum = (num) => {
    const absoluteNum = Math.abs(num);
    return absoluteNum
      .toString()
      .split('')
      .reduce((sum, digit) => sum + parseInt(digit, 10), 0);
  };

  // Map to an array of objects to preserve original index for stable sorting
  return nums
    .map((val, index) => ({
      val,
      index,
      sum: getDigitSum(val),
    }))
    .sort((a, b) => {
      if (a.sum !== b.sum) {
        return a.sum - b.sum;
      }
      return a.index - b.index;
    })
    .map((item) => item.val);
};
