const getMaxTriples = (n) => {
  // The value of a[i] = i^2 - i + 1.
  // We need to find the number of triples (a[i], a[j], a[k]) such that (a[i] + a[j] + a[k]) % 3 == 0.
  // Let's analyze a[i] % 3 for i = 1, 2, 3, ...
  // i = 1: 1^2 - 1 + 1 = 1. 1 % 3 = 1
  // i = 2: 2^2 - 2 + 1 = 3. 3 % 3 = 0
  // i = 3: 3^2 - 3 + 1 = 7. 7 % 3 = 1
  // i = 4: 4^2 - 4 + 1 = 13. 13 % 3 = 1
  // i = 5: 5^2 - 5 + 1 = 21. 21 % 3 = 0
  // i = 6: 6^2 - 6 + 1 = 31. 31 % 3 = 1
  // Pattern of a[i] % 3: 1, 0, 1, 1, 0, 1, ...
  // It repeats every 3 terms: [1, 0, 1].

  // Count how many elements have remainder 0, 1, and 2 when divided by 3.
  // Remainder 0 occurs when i % 3 == 2.
  // Remainder 1 occurs when i % 3 == 1 or i % 3 == 0.
  // Remainder 2 never occurs because i^2 - i + 1 mod 3 is always 0 or 1.

  let count0 = 0;
  let count1 = 0;

  // For i from 1 to n:
  // i % 3 == 1 -> a[i] % 3 = 1
  // i % 3 == 2 -> a[i] % 3 = 0
  // i % 3 == 0 -> a[i] % 3 = 1

  // Number of i in [1, n] where i % 3 == 2:
  count0 = Math.floor((n + 1) / 3);
  // Number of i in [1, n] where i % 3 == 1 or 0:
  count1 = n - count0;

  // We need (r_i + r_j + r_k) % 3 == 0, where r is the remainder.
  // Possible combinations of (r_i, r_j, r_k) using only 0s and 1s:
  // 1. (0, 0, 0): 0+0+0 = 0. Ways: C(count0, 3)
  // 2. (1, 1, 1): 1+1+1 = 3. Ways: C(count1, 3)
  // 3. (0, 1, 1): 0+1+1 = 2. (Not divisible by 3)
  // 4. (0, 0, 1): 0+0+1 = 1. (Not divisible by 3)

  const combinations3 = (num) => {
    if (num < 3) return 0;
    // nC3 = n * (n-1) * (n-2) / 6
    return (num * (num - 1) * (num - 2)) / 6;
  };

  return combinations3(count0) + combinations3(count1);
};
