      if (charCode >= 65 && charCode <= 90) {
        strength++;
      } else if (charCode >= 97 && charCode <= 122) {
        strength--;
      }
    }

    if (strength > maxStrength) {
      maxStrength = strength;
      strongestIdx = i;
    }
  }

  return `${class_name}.${extensions[strongestIdx]}`;
};
