const cycpatternCheck = (a, b) => {
  const l = b.length;
  if (l === 0) return true;
  if (l > a.length) return false;

  // A string contains a rotation of b if and only if 
  // it contains a substring of length l that is a substring of b + b.
  // However, the problem asks if any rotation of b is a substring of a.
  // This means we check every substring of a with length l to see if it's a rotation of b.
  const pat = b + b;

  for (let i = 0; i <= a.length - l; i++) {
    const sub = a.substring(i, i + l);
    if (pat.includes(sub)) {
      return true;
    }
  }

  return false;
};
