const intToMiniRoman = (number) => {
  let num = [1, 4, 5, 9, 10, 40, 50, 90, 100, 400, 500, 900, 1000]
  let sym = ['i', 'iv', 'v', 'ix', 'x', 'xl', 'l', 'xc', 'c', 'cd', 'd', 'cm', 'm']
  let i = 12
  let res = ''
  while (number) {
    let div = Math.floor(number / num[i])
    while (div) {
      res += sym[i]
      div -= 1
    }
    number -= Math.floor(number / num[i]) * num[i]
    i -= 1
  }
  return res
}
