const evenOddCount = (num) => {
  let o = 0;
  let e = 0;

  // Handle negative numbers and zero
  let n = Math.abs(num);

  if (n === 0) return [1, 0];

  while (n > 0) {
    let digit = n % 10;
    if (digit % 2 === 0) {
      e++;
    } else {
      o++;
    }
    n = Math.floor(n / 10);
  }

  return [e, o];
};
