const findMax = (words) => {
  if (words.length === 0) {
    return '';
  }

  let maxUniqueCount = -1;
  let resultWord = '';

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    // Use a Set to count unique characters in the current word
    const uniqueCount = new Set(word).size;

    if (uniqueCount > maxUniqueCount) {
      maxUniqueCount = uniqueCount;
      resultWord = word;
    } else if (uniqueCount === maxUniqueCount) {
      // If unique counts are equal, pick the lexicographically smaller word
      if (word < resultWord) {
        resultWord = word;
      }
    }
  }

  return resultWord;
};
