const doAlgebra = (operator, operand) => {
  // Create copies to avoid mutating the original input arrays
  let ops = [...operator];
  let nums = [...operand];

  while (ops.length > 0) {
    let found = false;

    // 1. Exponentiation (Right-to-Left)
    for (let i = ops.length - 1; i >= 0; i--) {
      if (ops[i] === '**') {
        nums[i] = Math.pow(nums[i], nums[i + 1]);
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        found = true;
        break;
      }
    }
    if (found) continue;

    // 2. Multiplication and Floor Division (Left-to-Right)
    for (let i = 0; i < ops.length; i++) {
      if (ops[i] === '*') {
        nums[i] = nums[i] * nums[i + 1];
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        found = true;
        break;
      } else if (ops[i] === '//') {
        nums[i] = Math.floor(nums[i] / nums[i + 1]);
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        found = true;
        break;
      }
    }
    if (found) continue;

    // 3. Addition and Subtraction (Left-to-Right)
    for (let i = 0; i < ops.length; i++) {
      if (ops[i] === '+') {
        nums[i] = nums[i] + nums[i + 1];
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        found = true;
        break;
      } else if (ops[i] === '-') {
        nums[i] = nums[i] - nums[i + 1];
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        found = true;
        break;
      }
    }
    if (!found) break; // Prevent infinite loop if unknown operator is passed
  }

  return nums[0];
};
