const solve = (s) => {
  let hasLetter = false;
  let result = '';

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    const code = char.charCodeAt(0);

    if (code >= 65 && code <= 90) {
      // Uppercase to Lowercase
      result += String.fromCharCode(code + 32);
      hasLetter = true;
    } else if (code >= 97 && code <= 122) {
      // Lowercase to Uppercase
      result += String.fromCharCode(code - 32);
      hasLetter = true;
    } else {
      result += char;
    }
  }

  if (hasLetter) {
    return result;
  }

  // If no letters were found, reverse the original string
  return s.split('').reverse().join('');
};
