const separateParenGroups = (paren_string) => {
  const cleaned = paren_string.replace(/\s+/g, '');
  const groups = [];
  let currentGroup = '';
  let balance = 0;

  for (const char of cleaned) {
    currentGroup += char;
    if (char === '(') {
      balance++;
    } else if (char === ')') {
      balance--;
    }

    if (balance === 0 && currentGroup.length > 0) {
      groups.push(currentGroup);
      currentGroup = '';
    }
  }

  return groups;
};
```

