const separateParenGroups = (paren_string) => {
  const cleaned = paren_string.replace(/\s+/g, '');
  const groups = [];
  let currentGroup = '';
  let depth = 0;

  for (const char of cleaned) {
    currentGroup += char;
    if (char === '(') {
      depth++;
    } else if (char === ')') {
      depth--;
    }

    if (depth === 0 && currentGroup.length > 0) {
      groups.push(currentGroup);
      currentGroup = '';
    }
  }

  return groups;
};
