const findZero = (xs) => {
  const poly = (x) => {
    let res = 0;
    for (let i = 0; i < xs.length; i++) {
      res += xs[i] * Math.pow(x, i);
    }
    return res;
  };

  // Bisection method
  // Since the polynomial has an even number of coefficients, its degree is odd.
  // An odd-degree polynomial always has at least one real root.
  let low = -1.0;
  let high = 1.0;

  // Expand range until we find signs that differ
  while (poly(low) * poly(high) > 0) {
    low *= 2;
    high *= 2;
  }

  // Binary search for the root
  for (let i = 0; i < 100; i++) {
    let mid = (low + high) / 2;
    if (poly(low) * poly(mid) <= 0) {
      high = mid;
    } else {
      low = mid;
    }
  }

  return (low + high) / 2;
};
```

