const primeFib = (n) => {
  const isPrime = (num) => {
    if (num < 2) return false;
    for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
      if (num % i === 0) return false;
    }
    return true;
  };

  let count = 0;
  let a = 0;
  let b = 1;

  while (count < n) {
    let temp = a + b;
    a = b;
    b = temp;

    if (isPrime(a)) {
      count++;
      if (count === n) return a;
    }
  }
};
