const decodeCyclic = (s) => {
  const n = s.length;
  if (n === 0) return "";

  // The cyclic encoding typically involves shifting each character 
  // by its position in the string (index i).
  // To decode, we subtract the index i from the character code.
  return s.split("").map((ch, i) => {
    const charCode = ch.charCodeAt(0);
    const startCode = "a".charCodeAt(0);

    // Formula: (current_pos - shift - start) % 26
    // We add 26 * n to ensure the result is positive before the modulo
    let decodedCode = ((charCode - startCode - i) % 26);
    if (decodedCode < 0) decodedCode += 26;

    return String.fromCharCode(decodedCode + startCode);
  }).join("");
};
```

