const modp = (n, p) => {
  let res = 1n;
  let base = 2n;
  let exp = BigInt(n);
  let mod = BigInt(p);

  while (exp > 0n) {
    if (exp % 2n === 1n) {
      res = (res * base) % mod;
    }
    base = (base * base) % mod;
    exp = exp / 2n;
  }

  return Number(res);
};
