const decodeShift = (s) => {
  let decoded = "";
  for (let i = 0; i < s.length; i++) {
    const charCode = s.charCodeAt(i);
    // The shift is based on the index i. 
    // To decode, we subtract the shift value from the character code.
    decoded += String.fromCharCode(charCode - i);
  }
  return decoded;
};
