const circularShift = (x, shift) => {
  const s = x.toString();
  const n = s.length;

  if (shift > n) {
    return s.split('').reverse().join('');
  }

  const shiftAmount = shift % n;
  if (shiftAmount === 0) {
    return s;
  }

  const rightPart = s.slice(-shiftAmount);
  const leftPart = s.slice(0, n - shiftAmount);
  return rightPart + leftPart;
};
```

