const numericalLetterGrade = (grades) => {
  const gradingScale = [
    { threshold: 4.0, grade: 'A+' },
    { threshold: 3.7, grade: 'A' },
    { threshold: 3.3, grade: 'A-' },
    { threshold: 3.0, grade: 'B+' },
    { threshold: 2.7, grade: 'B' },
    { threshold: 2.3, grade: 'B-' },
    { threshold: 2.0, grade: 'C+' },
    { threshold: 1.7, grade: 'C' },
    { threshold: 1.3, grade: 'C-' },
    { threshold: 1.0, grade: 'D+' },
    { threshold: 0.7, grade: 'D' },
    { threshold: 0.0, grade: 'D-' },
  ];

  return grades.map(gpa => {
    if (gpa === 0) return 'E';

    for (let i = 0; i < gradingScale.length; i++) {
      const { threshold, grade } = gradingScale[i];
      // The first element is a strict equality check for 4.0
      if (i === 0) {
        if (gpa === 4.0) return grade;
      } else {
        // For the rest, the table indicates "> threshold"
        if (gpa > threshold) return grade;
      }
    }
    return 'E';
  });
};
```

