const startsOneEnds = (n) => {
  if (n <= 0) return 0;
  if (n === 1) return 1;

  // Total n-digit numbers: 9 * 10^(n-1)
  // Numbers starting with 1: 1 * 10^(n-1)
  // Numbers ending with 1: 9 * 10^(n-2)
  // Numbers starting AND ending with 1: 1 * 10^(n-2)

  // Using Inclusion-Exclusion Principle: |A ∪ B| = |A| + |B| - |A ∩ B|
  // Count = 10^(n-1) + 9 * 10^(n-2) - 10^(n-2)
  // Count = 10^(n-1) + 8 * 10^(n-2)

  const power10nMinus1 = Math.pow(10, n - 1);
  const power10nMinus2 = Math.pow(10, n - 2);

  return power10nMinus1 + (8 * power10nMinus2);
};
```

