const solve = (N) => {
  // Calculate the sum of the digits of N
  let sum = 0;
  let tempN = N;
  while (tempN > 0) {
    sum += tempN % 10;
    tempN = Math.floor(tempN / 10);
  }

  // Convert the sum to a binary string
  return sum.toString(2);
};
