const getRow = (lst, x) => {
  const result = [];

  for (let r = 0; r < lst.length; r++) {
    const row = lst[r];
    const rowCoords = [];
    for (let c = 0; c < row.length; c++) {
      if (row[c] === x) {
        rowCoords.push([r, c]);
      }
    }

    // Sort coordinates of the row by columns in descending order
    rowCoords.sort((a, b) => b[1] - a[1]);

    // Add the sorted row coordinates to the final result
    // Since we iterate through rows from 0 to length-1, 
    // the result is already sorted by rows in ascending order.
    for (let coord of rowCoords) {
      result.push(coord);
    }
  }

  return result;
};
```

