const sortArray = (array) => {
  if (array.length === 0) return [];
  if (array.length === 1) return [...array];

  const first = array[0];
  const last = array[array.length - 1];
  const sum = first + last;

  const sortedCopy = [...array];

  if (sum % 2 !== 0) {
    // Ascending order
    sortedCopy.sort((a, b) => a - b);
  } else {
    // Descending order
    sortedCopy.sort((a, b) => b - a);
  }

  return sortedCopy;
};
```

