const isBored = (S) => {
  // Split the string into sentences using a regular expression that matches '.', '?', or '!'
  const sentences = S.split(/[.?!]/);
  let count = 0;

  for (let sentence of sentences) {
    // Trim leading whitespace to find the first word
    const trimmedSentence = sentence.trim();

    // Check if the sentence starts with the word "I"
    // We ensure it is exactly "I" and not a word starting with I (like "Ice")
    if (trimmedSentence.startsWith('I')) {
      // Check if "I" is followed by a space or is the end of the string
      if (trimmedSentence.length === 1 || trimmedSentence[1] === ' ') {
        count++;
      }
    }
  }

  return count;
};
