const checkDictCase = (dict) => {
  const keys = Object.keys(dict);
  if (keys.length === 0) {
    return false;
  }

  let allLower = true;
  let allUpper = true;

  for (let key of keys) {
    // Object.keys returns strings, but we must ensure the key 
    // is actually a string representation of a lowercase/uppercase string.
    // If the key was a number, it's converted to a string.
    // The problem states "all keys are strings in lower case or all keys are strings in upper case".

    // Check if key is strictly equal to its lowercase version
    if (key !== key.toLowerCase()) {
      allLower = false;
    }
    // Check if key is strictly equal to its uppercase version
    if (key !== key.toUpperCase()) {
      allUpper = false;
    }

    // If it's neither all lower nor all upper, we can stop early
    if (!allLower && !allUpper) {
      return false;
    }
  }

  return allLower || allUpper;
};
