const closestInteger = (value) => {
  const num = parseFloat(value);

  // Math.round() in JS rounds .5 towards positive infinity (e.g., -14.5 -> -14).
  // The requirement is to round away from zero (e.g., -14.5 -> -15).
  if (num >= 0) {
    return Math.round(num);
  } else {
    // For negative numbers, we can mirror the number, round it, and mirror it back.
    return -Math.round(-num);
  }
};
```

