  if (x > y) {
    return -1;
  }

  // Start from the upper bound and go downwards to find the biggest even integer
  let start = Math.floor(y);
  for (let i = start; i >= x; i--) {
    if (i % 2 === 0) {
      return i;
    }
  }

  return -1;
};
