const uniqueDigits = (x) => {
  const result = [];

  for (let i = 0; i < x.length; i++) {
    const numStr = x[i].toString();
    let hasEvenDigit = false;

    for (let j = 0; j < numStr.length; j++) {
      const digit = parseInt(numStr[j], 10);
      if (digit % 2 === 0) {
        hasEvenDigit = true;
        break;
      }
    }

    if (!hasEvenDigit) {
      result.push(x[i]);
    }
  }

  return result.sort((a, b) => a - b);
};
```

