const uniqueDigits = (x) => {
  const result = x.filter(num => {
    const digits = num.toString().split('');
    // Check if every digit is odd (not even)
    return digits.every(digit => parseInt(digit, 10) % 2 !== 0);
  });

  // Return the filtered list sorted in increasing order
  return result.sort((a, b) => a - b);
};
