const f = (n) => {
  const result = [];
  for (let i = 1; i <= n; i++) {
    if (i % 2 === 0) {
      // Factorial for even i
      let fact = 1;
      for (let j = 1; j <= i; j++) {
        fact *= j;
      }
      result.push(fact);
    } else {
      // Sum from 1 to i for odd i
      let sum = 0;
      for (let j = 1; j <= i; j++) {
        sum += j;
      }
      result.push(sum);
    }
  }
  return result;
};
