const evenOddPalindrome = (n) => {
  const isPalindrome = (num) => {
    const s = num.toString();
    const len = s.length;
    for (let i = 0; i < len / 2; i++) {
      if (s[i] !== s[len - 1 - i]) {
        return false;
      }
    }
    return true;
  };

  let evenCount = 0;
  let oddCount = 0;

  for (let i = 1; i <= n; i++) {
    if (isPalindrome(i)) {
      if (i % 2 === 0) {
        evenCount++;
      } else {
        oddCount++;
      }
    }
  }

  return [evenCount, oddCount];
};
