const countNums = (arr) => {
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    let num = arr[i];
    let str = num.toString();
    let sum = 0;

    for (let j = 0; j < str.length; j++) {
      if (str[j] === '-') {
        // The first digit following the minus sign is treated as negative
        sum -= parseInt(str[j + 1]);
        j++; // Skip the digit we just processed
      } else {
        sum += parseInt(str[j]);
      }
    }

    if (sum > 0) {
      count++;
    }
  }
  return count;
};
