const moveOneBall = (arr) => {
  if (arr.length === 0) {
    return true;
  }

  let count = 0;
  const n = arr.length;

  // A right-shifted sorted array can have at most one point where 
  // the current element is greater than the next element.
  for (let i = 0; i < n; i++) {
    if (arr[i] > arr[(i + 1) % n]) {
      count++;
    }
  }

  // If the array is sorted, count will be 0 (if all elements are same) or 1 (at the wrap-around).
  // Since elements are unique, a sorted array shifted will have exactly one drop 
  // (at the point where the largest element meets the smallest) or zero drops (if already sorted).
  return count <= 1;
};
```

