const countNums = (arr) => {
  let count = 0;
  for (let num of arr) {
    const str = num.toString();
    let sum = 0;
    for (let i = 0; i < str.length; i++) {
      if (str[i] === '-') {
        // The first digit after the minus sign is treated as negative
        sum -= parseInt(str[i + 1], 10);
        i++; // Skip the digit we just processed
      } else {
        sum += parseInt(str[i], 10);
      }
    }
    if (sum > 0) {
      count++;
    }
  }
  return count;
};
