const isSorted = (lst) => {
  if (lst.length == 0) { return true }
  let dup = 1
  let pre = lst[0]
  for (let i = 1; i < lst.length; i++) {
    if (lst[i] < pre) { return false }
    if (lst[i] == pre) {
      dup += 1;
      if (dup == 3) { return false }
    } else {
      pre = lst[i]
      dup = 1
    }
  }
  return true
}

const moveOneBall = (arr) => {
  if (arr.length === 0) return true;

  const n = arr.length;
  let current = [...arr];

  for (let i = 0; i < n; i++) {
    if (isSorted(current)) {
      return true;
    }
    // Perform one right shift
    const lastElement = current.pop();
    current.unshift(lastElement);
  }

  return false;
}
