const moveOneBall = (arr) => {
  if (arr.length === 0) {
    return true;
  }

  let count = 0;
  const n = arr.length;

  // A right-shifted sorted array (with unique elements) will have 
  // at most one point where arr[i] > arr[i + 1].
  for (let i = 0; i < n - 1; i++) {
    if (arr[i] > arr[i + 1]) {
      count++;
    }
  }

  // If there is more than one "drop", it can't be sorted by rotation.
  if (count > 1) {
    return false;
  }

  // If there is exactly one drop, the last element must be less than or 
  // equal to the first element to ensure the rotation connects correctly.
  if (count === 1 && arr[n - 1] > arr[0]) {
    return false;
  }

  return true;
};
