const exchange = (lst1, lst2) => {
  let oddInLst1 = 0;
  for (let i = 0; i < lst1.length; i++) {
    if (lst1[i] % 2 !== 0) {
      oddInLst1++;
    }
  }

  let evenInLst2 = 0;
  for (let i = 0; i < lst2.length; i++) {
    if (lst2[i] % 2 === 0) {
      evenInLst2++;
    }
  }

  if (evenInLst2 >= oddInLst1) {
    return "YES";
  } else {
    return "NO";
  }
};
