const reverseDelete = (s, c) => {
  // Create a set of characters to delete for O(1) lookup
  const deleteSet = new Set(c);

  // Filter out characters that are present in the deleteSet
  let resultString = "";
  for (let char of s) {
    if (!deleteSet.has(char)) {
      resultString += char;
    }
  }

  // Check if the resulting string is a palindrome
  const reversedString = resultString.split('').reverse().join('');
  const isPalindrome = resultString === reversedString;

  // Return as a tuple (array in JavaScript)
  return [resultString, isPalindrome];
};
```

