const maxFill = (grid, capacity) => {
  let totalLowerings = 0;

  for (let i = 0; i < grid.length; i++) {
    let waterInWell = 0;
    for (let j = 0; j < grid[i].length; j++) {
      if (grid[i][j] === 1) {
        waterInWell++;
      }
    }

    if (waterInWell > 0) {
      // Calculate how many times the bucket must be lowered for this specific well.
      // We use Math.ceil(waterInWell / capacity) to get the number of trips.
      totalLowerings += Math.ceil(waterInWell / capacity);
    }
  }

  return totalLowerings;
};
