const maxFill = (grid, capacity) => {
  let totalTrips = 0;

  for (let i = 0; i < grid.length; i++) {
    let waterInWell = 0;
    for (let j = 0; j < grid[i].length; j++) {
      if (grid[i][j] === 1) {
        waterInWell++;
      }
    }

    if (waterInWell > 0) {
      // Calculate number of trips for this specific well.
      // Math.ceil(waterInWell / capacity) gives the number of times 
      // the bucket must be lowered to empty the well.
      totalTrips += Math.ceil(waterInWell / capacity);
    }
  }

  return totalTrips;
};
