const selectWords = (s, n) => {
  if (!s) return [];

  const words = s.split(' ');
  const vowels = 'aeiouAEIOU';
  const result = [];

  for (const word of words) {
    if (word === '') continue;

    let consonantCount = 0;
    for (let i = 0; i < word.length; i++) {
      const char = word[i];
      // Check if character is a letter and not a vowel
      if (/[a-zA-Z]/.test(char) && !vowels.includes(char)) {
        consonantCount++;
      }
    }

    if (consonantCount === n) {
      result.push(word);
    }
  }

  return result;
};
