const getClosestVowel = (word) => {
  const vowels = 'aeiouAEIOU';

  // Iterate from the right side of the word
  // Start at length - 2 and end at 1 to ensure the vowel is between two characters
  for (let i = word.length - 2; i > 0; i--) {
    const char = word[i];
    const prevChar = word[i - 1];
    const nextChar = word[i + 1];

    // Check if current character is a vowel
    if (vowels.includes(char)) {
      // Check if characters on both sides are NOT vowels (consonants)
      if (!vowels.includes(prevChar) && !vowels.includes(nextChar)) {
        return char;
      }
    }
  }

  return "";
};
```

