const getOddCollatz = (n) => {
  const odds = [];
  let current = n;

  while (current !== 1) {
    if (current % 2 !== 0) {
      odds.push(current);
    }
    if (current % 2 === 0) {
      current = current / 2;
    } else {
      current = 3 * current + 1;
    }
  }

  odds.push(1);
  return odds.sort((a, b) => a - b);
};
