const isSorted = (lst) => {
  const counts = {};

  for (let i = 0; i < lst.length; i++) {
    const current = lst[i];

    // Check if sorted in ascending order
    if (i > 0 && current < lst[i - 1]) {
      return false;
    }

    // Track occurrences of each number
    counts[current] = (counts[current] || 0) + 1;

    // If more than 1 duplicate (meaning 3 or more of the same number), return false
    if (counts[current] > 2) {
      return false;
    }
  }

  return true;
};
