const intersection = (interval1, interval2) => {
  const isPrime = (p) => {
    if (p < 2) return false;
    for (let k = 2; k <= Math.sqrt(p); k++) {
      if (p % k === 0) return false;
    }
    return true;
  };

  const [start1, end1] = interval1;
  const [start2, end2] = interval2;

  // Find the boundaries of the intersection
  const startMax = Math.max(start1, start2);
  const endMin = Math.min(end1, end2);

  // If startMax > endMin, there is no intersection
  if (startMax > endMin) {
    return "NO";
  }

  // The length of a closed interval [a, b] is b - a
  const length = endMin - startMax;

  return isPrime(length) ? "YES" : "NO";
};
