const minPath = (grid, k) => {
  const n = grid.length;
  let minVal = Infinity;
  let startPos = [-1, -1];

  // Find the cell with the minimum value in the grid
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] < minVal) {
        minVal = grid[r][c];
        startPos = [r, c];
      }
    }
  }

  // If k is 1, the path is just the minimum element
  if (k === 1) {
    return [minVal];
  }

  const [r, c] = startPos;
  const dr = [0, 0, 1, -1];
  const dc = [1, -1, 0, 0];
  let minNeighbor = Infinity;

  // Find the smallest neighbor of the minimum element
  for (let i = 0; i < 4; i++) {
    const nr = r + dr[i];
    const nc = c + dc[i];
    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
      if (grid[nr][nc] < minNeighbor) {
        minNeighbor = grid[nr][nc];
      }
    }
