        minVal = grid[r][c];
        minR = r;
        minC = c;
      }
    }
  }

  // If k is 1, the path is just the minimum value
  if (k === 1) {
    return [minVal];
  }

  // To get the lexicographically smallest path of length k,
  // we start at the minimum value. Then we look for the smallest
  // neighbor of that minimum value.
  // Once we find the smallest neighbor (minNeighbor), the optimal strategy
  // is to bounce back and forth between the minimum value and its smallest neighbor.
  // This is because any other path would result in a larger value at the second position
  // or a larger value at the third position (since the minimum value is the smallest possible).

  let minNeighbor = Infinity;
  const dr = [-1, 1, 0, 0];
  const dc = [0, 0, -1, 1];

  for (let i = 0; i < 4; i++) {
    const nr = minR + dr[i];
    const nc = minC + dc[i];

    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
      if (grid[nr][nc] < minNeighbor) {
        minNeighbor = grid[nr][nc];
      }
    }
  }

  const result = [];
  for (let i = 0; i < k; i++) {
    if (i % 2 === 0) {
      result.push(minVal);
    } else {
      result.push(minNeighbor);
    }
  }

  return result;
};
