const tri = (n) => {
  if (n < 0) return [];
  const sequence = new Array(n + 1);

  // The problem defines tri(1) = 3. 
  // The example tri(3) = [1, 3, 2, 8] implies:
  // index 0: 1
  // index 1: 3
  // index 2: 2
  // index 3: 8
  // This suggests the sequence is 0-indexed and tri(0) = 1.

  sequence[0] = 1;

  for (let i = 1; i <= n; i++) {
    if (i === 1) {
      sequence[i] = 3;
    } else if (i % 2 === 0) {
      sequence[i] = 1 + i / 2;
    } else {
      // tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
      // To solve for tri(n), we need tri(n+1).
      // Since n is odd, n+1 is even.
      // tri(n+1) = 1 + (n+1)/2
      const tri_n_plus_1 = 1 + (i + 1) / 2;
      sequence[i] = sequence[i - 1] + sequence[i - 2] + tri_n_plus_1;
    }
  }

  return sequence;
};
