const isNested = (string) => {
  let count = 0;
  let maxDepth = 0;

  for (let char of string) {
    if (char === '[') {
      count++;
      if (count > maxDepth) {
        maxDepth = count;
      }
    } else if (char === ']') {
      if (count > 0) {
        count--;
      }
    }
  }

  // A valid subsequence with nesting exists if we were able to 
  // reach a depth of 2 or more while maintaining balance.
  // However, the problem asks for a "valid subsequence".
  // A valid nested subsequence is simply any occurrence of "[[]]".
  // This is equivalent to checking if there is a '[' followed by another '[' 
  // which is then followed by two ']' later in the string.

  let openBrackets = 0;
  for (let char of string) {
    if (char === '[') {
      openBrackets++;
    } else if (char === ']' && openBrackets > 1) {
      // If we encounter a closing bracket while we have at least 2 open ones,
      // it means at least one pair is nested within another.
      return true;
    } else if (char === ']' && openBrackets === 1) {
      openBrackets--;
    }
  }

  return false;
};
