const fileNameCheck = (file_name) => {
  // Check for exactly one dot
  const parts = file_name.split('.');
  if (parts.length !== 2) {
    return 'No';
  }

  const [beforeDot, afterDot] = parts;

  // Substring before the dot should not be empty
  if (beforeDot.length === 0) {
    return 'No';
  }

  // Substring before the dot starts with a letter from the latin alphabet
  const firstChar = beforeDot[0];
  if (!((firstChar >= 'a' && firstChar <= 'z') || (firstChar >= 'A' && firstChar <= 'Z'))) {
    return 'No';
  }

  // Substring after the dot should be one of ['txt', 'exe', 'dll']
  const validExtensions = ['txt', 'exe', 'dll'];
  if (!validExtensions.includes(afterDot)) {
    return 'No';
  }

  // There should not be more than three digits ('0'-'9') in the file's name
  let digitCount = 0;
  for (let i = 0; i < file_name.length; i++) {
    if (file_name[i] >= '0' && file_name[i] <= '9') {
      digitCount++;
    }
  }
  if (digitCount > 3) {
    return 'No';
  }

  return 'Yes';
};
