const orderByPoints = (nums) => {
  const getDigitSum = (num) => {
    const absoluteValue = Math.abs(num);
    const digits = absoluteValue.toString().split('');
    return digits.reduce((sum, digit) => sum + parseInt(digit, 10), 0);
  };

  // We map the array to include the original index to ensure a stable sort,
  // as JavaScript's Array.prototype.sort() is stable in modern environments,
  // but explicit index handling guarantees the requirement.
  return nums
    .map((val, index) => ({ val, index, sum: getDigitSum(val) }))
    .sort((a, b) => {
      if (a.sum !== b.sum) {
        return a.sum - b.sum;
      }
      return a.index - b.index;
    })
    .map(item => item.val);
};

