const getMaxTriples = (n) => {
  // The sequence is a[i] = i^2 - i + 1 for i = 1 to n.
  // We need to find triples (a[i], a[j], a[k]) such that (a[i] + a[j] + a[k]) % 3 == 0.
  // Let's analyze a[i] mod 3:
  // i % 3 == 1: a[i] = 1^2 - 1 + 1 = 1. (1 mod 3)
  // i % 3 == 2: a[i] = 2^2 - 2 + 1 = 3. (0 mod 3)
  // i % 3 == 0: a[i] = 0^2 - 0 + 1 = 1. (1 mod 3)

  // So, for any i:
  // If i is a multiple of 3, a[i] % 3 = 1.
  // If i % 3 == 1, a[i] % 3 = 1.
  // If i % 3 == 2, a[i] % 3 = 0.

  // Let count0 be the number of elements where a[i] % 3 == 0.
  // Let count1 be the number of elements where a[i] % 3 == 1.
  // Let count2 be the number of elements where a[i] % 3 == 2.

  // Based on the analysis:
  // count0 = number of i in [1, n] such that i % 3 == 2.
  // count1 = number of i in [1, n] such that i % 3 == 1 or i % 3 == 0.
  // count2 = 0 (since a[i] mod 3 is never 2).

  const count0 = Math.floor((n + 1) / 3); 
  // Correction: i % 3 == 2 occurs at 2, 5, 8... 
  // The number of such elements is floor((n - 2) / 3) + 1 if n >= 2, else 0.
  const c0 = n >= 2 ? Math.floor((n - 2) / 3) + 1 : 0;
  const c1 = n - c0;
  const c2 = 0;

  // For (a[i] + a[j] + a[k]) % 3 == 0:
  // Possible combinations of (mod 3) values:
  // 1. (0, 0, 0)
  // 2. (1, 1, 1)
  // 3. (2, 2, 2)
  // 4. (0, 1, 2)

  let totalTriples = 0;

  // Case 1: (0, 0, 0)
  if (c0 >= 3) {
    totalTriples += (c0 * (c0 - 1) * (c0 - 2)) / 6;
  }

  // Case 2: (1, 1, 1)
  if (c1 >= 3) {
    totalTriples += (c1 * (c1 - 1) * (c1 - 2)) / 6;
  }

  // Case 3: (2, 2, 2)
  if (c2 >= 3) {
    totalTriples += (c2 * (c2 - 1) * (c2 - 2)) / 6;
  }

  // Case 4: (0, 1, 2)
  totalTriples += (c0 * c1 * c2);

  return totalTriples;
};
