  // We need to find the number of triples (a[i], a[j], a[k]) such that 
  // (a[i] + a[j] + a[k]) % 3 == 0.

  // Let's analyze a[i] mod 3:
  // i = 1: 1^2 - 1 + 1 = 1. 1 % 3 = 1
  // i = 2: 2^2 - 2 + 1 = 3. 3 % 3 = 0
  // i = 3: 3^2 - 3 + 1 = 7. 7 % 3 = 1
  // i = 4: 4^2 - 4 + 1 = 13. 13 % 3 = 1
  // i = 5: 5^2 - 5 + 1 = 21. 21 % 3 = 0
  // i = 6: 6^2 - 6 + 1 = 31. 31 % 3 = 1

  // Pattern of a[i] % 3:
  // i % 3 == 1: (1)^2 - 1 + 1 = 1 mod 3
  // i % 3 == 2: (2)^2 - 2 + 1 = 3 = 0 mod 3
  // i % 3 == 0: (0)^2 - 0 + 1 = 1 mod 3

  // So, a[i] % 3 is 0 if i % 3 == 2, and 1 if i % 3 == 1 or 0.
  // Let c0 be the count of elements where a[i] % 3 == 0.
  // Let c1 be the count of elements where a[i] % 3 == 1.
  // Let c2 be the count of elements where a[i] % 3 == 2.

  // From the pattern:
  // c0 = number of i in [1, n] such that i % 3 == 2.
  // c1 = number of i in [1, n] such that i % 3 == 1 or i % 3 == 0.
  // c2 = 0 (since a[i] % 3 is never 2).

  const c0 = Math.floor((n + 1) / 3);
  const c1 = n - c0;
  const c2 = 0;

  // A triple (x, y, z) sums to a multiple of 3 if:
  // 1. All three have the same remainder mod 3.
  // 2. All three have different remainders mod 3.

  // Case 1: All same remainder
  // - All 0s: combinations(c0, 3)
  // - All 1s: combinations(c1, 3)
  // - All 2s: combinations(c2, 3)

  // Case 2: All different remainders
  // - One 0, one 1, one 2: c0 * c1 * c2

  const combinations3 = (count) => {
    if (count < 3) return 0;
    return (count * (count - 1) * (count - 2)) / 6;
  };

  const result = combinations3(c0) + combinations3(c1) + combinations3(c2) + (c0 * c1 * c2);

