const getMaxTriples = (n) => {
  // The sequence is a[i] = i^2 - i + 1 for i = 1 to n.
  // We need to find triples (a[i], a[j], a[k]) where i < j < k and (a[i] + a[j] + a[k]) % 3 == 0.
  // Let's analyze a[i] mod 3:
  // i = 1: 1^2 - 1 + 1 = 1  => 1 mod 3
  // i = 2: 2^2 - 2 + 1 = 3  => 0 mod 3
  // i = 3: 3^2 - 3 + 1 = 7  => 1 mod 3
  // i = 4: 4^2 - 4 + 1 = 13 => 1 mod 3
  // i = 5: 5^2 - 5 + 1 = 21 => 0 mod 3
  // i = 6: 6^2 - 6 + 1 = 31 => 1 mod 3
  // Pattern of a[i] mod 3: 1, 0, 1, 1, 0, 1, ...
  // Specifically:
  // If i % 3 == 0, a[i] = (3k)^2 - 3k + 1 = 9k^2 - 3k + 1 ≡ 1 (mod 3)
  // If i % 3 == 1, a[i] = (3k+1)^2 - (3k+1) + 1 = 9k^2 + 6k + 1 - 3k - 1 + 1 = 9k^2 + 3k + 1 ≡ 1 (mod 3)
  // If i % 3 == 2, a[i] = (3k+2)^2 - (3k+2) + 1 = 9k^2 + 12k + 4 - 3k - 2 + 1 = 9k^2 + 9k + 3 ≡ 0 (mod 3)

  // Count how many elements have remainder 0 and remainder 1 mod 3.
  // Remainder 0 occurs when i % 3 == 2.
  // Remainder 1 occurs when i % 3 == 0 or i % 3 == 1.

  let count0 = 0;
  let count1 = 0;

  for (let i = 1; i <= n; i++) {
    if (i % 3 === 2) {
      count0++;
    } else {
      count1++;
    }
  }

  // A sum of three numbers is a multiple of 3 if:
  // 1. All three have the same remainder mod 3.
  // 2. They have distinct remainders (0, 1, 2).

  // In our case, we only have remainders 0 and 1.
  // Possible combinations for (r1 + r2 + r3) % 3 == 0:
  // - (0, 0, 0): count0C3
  // - (1, 1, 1): count1C3
  // - (0, 1, 2): Not possible since we have no elements with remainder 2.

  const nCr3 = (num) => {
    if (num < 3) return 0;
    return (num * (num - 1) * (num - 2)) / 6;
  };

  return nCr3(count0) + nCr3(count1);
