const bf = (planet1, planet2) => {
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune"
  ];

  const idx1 = planets.indexOf(planet1);
  const idx2 = planets.indexOf(planet2);

  if (idx1 === -1 || idx2 === -1) {
    return [];
  }

  const start = Math.min(idx1, idx2);
  const end = Math.max(idx1, idx2);

  const result = [];
  for (let i = start + 1; i < end; i++) {
    result.push(planets[i]);
  }

