const sortedListSum = (lst) => {
  // Filter out strings that have odd lengths
  const filtered = lst.filter(str => str.length % 2 === 0);

  // Sort the list:
  // 1. Ascending by length of each word
  // 2. Alphabetically if lengths are the same
  filtered.sort((a, b) => {
    if (a.length !== b.length) {
      return a.length - b.length;
    }
    return a.localeCompare(b);
  });

  return filtered;
};
