const getMaxTriples = (n) => {
  // The formula is a[i] = i^2 - i + 1.
  // We need to find the number of triples (i, j, k) such that 1 <= i < j < k <= n
  // and (a[i] + a[j] + a[k]) % 3 == 0.

  // Let's analyze a[i] mod 3:
  // i % 3 == 1: a[i] = 1^2 - 1 + 1 = 1. (1 mod 3)
  // i % 3 == 2: a[i] = 2^2 - 2 + 1 = 3. (0 mod 3)
  // i % 3 == 0: a[i] = 0^2 - 0 + 1 = 1. (1 mod 3)

  // So, for any i:
  // If i is a multiple of 3, a[i] % 3 = 1.
  // If i % 3 == 1, a[i] % 3 = 1.
  // If i % 3 == 2, a[i] % 3 = 0.

  // Let count0 be the number of elements where a[i] % 3 == 0.
  // Let count1 be the number of elements where a[i] % 3 == 1.
  // Let count2 be the number of elements where a[i] % 3 == 2.

  // Based on the analysis:
  // a[i] % 3 is 0 if i % 3 == 2.
  // a[i] % 3 is 1 if i % 3 == 1 or i % 3 == 0.
  // a[i] % 3 is never 2.

  const count0 = Math.floor((n + 1) / 3); // Indices 2, 5, 8...
  // Wait, let's be precise:
  // i = 1: 1%3=1 -> a[1]=1 (1 mod 3)
  // i = 2: 2%3=2 -> a[2]=3 (0 mod 3)
  // i = 3: 3%3=0 -> a[3]=7 (1 mod 3)
  // i = 4: 4%3=1 -> a[4]=13 (1 mod 3)
  // i = 5: 5%3=2 -> a[5]=21 (0 mod 3)

  // count0: i is 2, 5, 8... (i = 3k - 1)
  // 3k - 1 <= n  => 3k <= n + 1 => k <= (n + 1) / 3
  const c0 = Math.floor((n + 1) / 3);

  // count1: i is 1, 3, 4, 6, 7, 9...
  // This is simply n - c0.
  const c1 = n - c0;

  // We need (a[i] + a[j] + a[k]) % 3 == 0.
  // Possible combinations of (mod 3) values that sum to 0 mod 3:
  // 1. (0, 0, 0)
  // 2. (1, 1, 1)
  // 3. (0, 1, 2) - Not possible since count2 is 0.

  // Number of ways to choose 3 from c0: c0 * (c0 - 1) * (c0 - 2) / 6
  // Number of ways to choose 3 from c1: c1 * (c1 - 1) * (c1 - 2) / 6

  const combinations3 = (count) => {
    if (count < 3) return 0;
    return (count * (count - 1) * (count - 2)) / 6;
  };

  return combinations3(c0) + combinations3(c1);
};
```

