          if (op === '-') values.push(left - right);
          if (op === '*') values.push(left * right);
          if (op === '//') values.push(Math.floor(left / right));
          if (op === '**') values.push(Math.pow(left, right));
        }
        operators.push(token);
      }
    }

    while (operators.length > 0) {
      let op = operators.pop();
      let right = values.pop();
      let left = values.pop();
      if (op === '+') values.push(left + right);
      if (op === '-') values.push(left - right);
      if (op === '*') values.push(left * right);
      if (op === '//') values.push(Math.floor(left / right));
      if (op === '**') values.push(Math.pow(left, right));
    }
    return values[0];
  };

  return evaluate(operator, operand);
};
